import numpy as np
from scipy.optimize import least_squares
t=df['t'].values;P=df['P'].values;y=df['dP_dt'].values
best=[]
for k in [0.5,0.8,1,1.2,1.5,2]:
  for K in [3,4,5,6,8,10]:
    for gname,g in [('P',P),('P2',P*P)]:
        for hname,h in [('P(1-P/K)',P*(1-P/K)),('P e^-P/K',P*np.exp(-P/K)),('P/(1+P/K)',P/(1+P/K))]:
            X=np.column_stack([1/P,g,t**k*h]); c=np.linalg.lstsq(X,y,rcond=None)[0]
            best.append((np.mean((X@c-y)**2)/np.var(y),k,K,gname,hname,np.round(c,3)))
best.sort(key=lambda z:z[0])
for b in best[:8]: print(b)
